/* Keep the course route ahead of supporting practice. */
.course-tool-menu { margin:40px 0 24px; padding-top:24px; border-top:2px solid var(--line-dark); }
.course-tool-choices { list-style:none; padding:0; display:grid; gap:16px; }
.course-tool-choices > li { padding:16px; margin:0; border-left:3px solid var(--red); background:var(--panel); }
.course-tool-choices > li > a { display:inline-flex; align-items:center; min-height:44px; font:700 1rem/1.5 var(--sans); }
.course-tool-choices p { margin:8px 0 0; }
#practice-tools { scroll-margin-top:160px; }
@media print { .course-tool-menu { border:0; } .course-tool-choices > li { background:white; } }
